#!/usr/bin/env bash
# materialize.sh: regenerate this repair package's files/ from the public, digest-pinned EdgeBench
# judge image plus repair.patch and the public crates.io cc-1.2.55.crate, then verify every
# resulting sha256 against source-lock.json ("materialize"."outputs"). Afterwards both Dockerfiles
# build unchanged:
#   ./materialize.sh && docker build -t <judge-tag> . && docker build -f Dockerfile.work -t <work-tag> .
#
# Files copied out of the EdgeBench images are deliberately NOT stored in Git; only our diffs are.
# Same layout as the packages generated by tools/make_materialize.py, with two differences: the
# originals are members of cas_rust_benchmark.tar.gz inside the judge image, and the four
# vendor-deps/cc/src/target/*.rs files come from crates.io.
#
# Steps: pull pinned image by digest if absent -> `docker create` + `docker cp` of the tarball (no
# container is run) -> check the tarball sha256 -> extract the two originals and check them ->
# apply repair.patch with `patch -p1` -> download cc-1.2.55.crate, check its sha256 (the package
# sha256 recorded in the tarball's vendor-deps/cc/.cargo-checksum.json) and extract four files ->
# verify sha256 of every output. Any mismatch fails loudly.
#
# Needs: bash, docker, GNU tar, GNU patch, sha256sum, python3, curl.
set -euo pipefail

PKG_NAME="rust_multicrate_reconstruction-v2"
JUDGE=seededge/edgebench.judge.rust_multicrate_reconstruction@sha256:d1d18aed02e81e5f09938de0272a76a72fab174a784613aefa3eb51443f6e408
TGZ=/home/workspace/cas_rust_benchmark/cas_rust_benchmark.tar.gz
BASE=(
  "cas_rust_benchmark/judge/tools/score.py|files/judge/tools/score.py"
  "cas_rust_benchmark/judge/hidden-tests/hidden-sources/cas-cli/tests/proptest/search_properties.rs|files/judge/hidden-tests/hidden-sources/cas-cli/tests/proptest/search_properties.rs"
  "cas_rust_benchmark/judge/hidden-tests/hidden-sources/crates/cas-search/src/bm25_tests/tests.rs|files/judge/hidden-tests/hidden-sources/crates/cas-search/src/bm25_tests/tests.rs"
  "cas_rust_benchmark/judge/hidden-tests/hidden-sources/crates/cas-search/src/hybrid.rs|files/judge/hidden-tests/hidden-sources/crates/cas-search/src/hybrid.rs"
  "cas_rust_benchmark/judge/hidden-tests/hidden-sources/crates/cas-search/tests/hybrid_integration.rs|files/judge/hidden-tests/hidden-sources/crates/cas-search/tests/hybrid_integration.rs"
)
CRATE_URL=https://static.crates.io/crates/cc/cc-1.2.55.crate
CC_FILES=(apple.rs generated.rs llvm.rs parser.rs)

cd "$(dirname "${BASH_SOURCE[0]}")"
PKG_DIR=$(pwd)
LOCK="$PKG_DIR/source-lock.json"

log() { echo "materialize[$PKG_NAME]: $*" >&2; }
die() { echo "materialize[$PKG_NAME]: ERROR: $*" >&2; exit 1; }
need() { command -v "$1" >/dev/null 2>&1 || die "missing required tool: $1"; }
need python3; need sha256sum; need patch; need docker; need tar; need curl
[ -f "$LOCK" ] || die "source-lock.json not found"

lockq() {  # lockq outputs | input PATH | tarball | crate
  python3 -I - "$LOCK" "$@" <<'PY'
import json, sys
m = json.load(open(sys.argv[1]))['materialize']
if sys.argv[2] == 'outputs':
    for k, v in sorted(m['outputs'].items()):
        print(v, k)
elif sys.argv[2] == 'input':
    hits = [i['sha256'] for i in m['inputs'] if i['path'] == sys.argv[3]]
    if not hits:
        sys.exit('no input entry for %s' % sys.argv[3])
    print(hits[0])
elif sys.argv[2] == 'tarball':
    print(m['tarball']['sha256'])
elif sys.argv[2] == 'crate':
    print(m['crates'][0]['sha256'])
PY
}
sha_of() { sha256sum "$1" | cut -d' ' -f1; }

STAGE=$(mktemp -d)
CID=""
cleanup() { [ -z "$CID" ] || docker rm -f "$CID" >/dev/null 2>&1 || true; rm -rf "$STAGE"; }
trap cleanup EXIT

# 1. Remove previous outputs so nothing stale survives.
while read -r _ path; do rm -f -- "$path"; done < <(lockq outputs)

# 2. Extract the tarball from the pinned judge image and the two originals from it.
if ! docker image inspect "$JUDGE" >/dev/null 2>&1; then
  log "pulling $JUDGE"
  docker pull --platform linux/amd64 "$JUDGE" >/dev/null || die "docker pull failed for $JUDGE"
fi
CID=$(docker create --platform linux/amd64 "$JUDGE" true) || die "docker create failed"
docker cp -L "$CID:$TGZ" "$STAGE/tarball.tar.gz" >/dev/null || die "docker cp $TGZ failed"
[ "$(sha_of "$STAGE/tarball.tar.gz")" = "$(lockq tarball)" ] || die "tarball sha256 differs from source-lock.json"
mkdir -p "$STAGE/t"
members=(); for row in "${BASE[@]}"; do members+=("${row%%|*}"); done
tar -xzf "$STAGE/tarball.tar.gz" -C "$STAGE/t" "${members[@]}" || die "could not extract originals"
for row in "${BASE[@]}"; do
  IFS='|' read -r member dst <<<"$row"
  want=$(lockq input "$TGZ!$member") || die "lock has no input entry for $member"
  got=$(sha_of "$STAGE/t/$member")
  [ "$got" = "$want" ] || die "original $member has sha256 $got, expected $want"
  mkdir -p "$(dirname "$dst")"; cp "$STAGE/t/$member" "$dst"
done
log "extracted ${#BASE[@]} original file(s); originals match source-lock.json"

# 3. Apply our diff.
patch -p1 --forward --batch --no-backup-if-mismatch --reject-file="$STAGE/rejects" -s < repair.patch \
  || die "repair.patch did not apply cleanly"
log "applied repair.patch"

# 4. Public crates.io source (not an image file): the four files the original tarball omits.
curl -fsSL --retry 3 -o "$STAGE/cc.crate" "$CRATE_URL" || die "download failed: $CRATE_URL"
[ "$(sha_of "$STAGE/cc.crate")" = "$(lockq crate)" ] || die "cc-1.2.55.crate sha256 mismatch"
tar -xzf "$STAGE/cc.crate" -C "$STAGE" "${CC_FILES[@]/#/cc-1.2.55/src/target/}" || die "could not extract cc files"
mkdir -p files/vendor-deps/cc/src/target
for f in "${CC_FILES[@]}"; do cp "$STAGE/cc-1.2.55/src/target/$f" "files/vendor-deps/cc/src/target/$f"; done
log "added ${#CC_FILES[@]} file(s) from $CRATE_URL"

# 5. Verify every output against source-lock.json.
bad=0; total=0
while read -r want path; do
  total=$((total + 1))
  if [ ! -f "$path" ]; then echo "MISSING  $path" >&2; bad=$((bad + 1)); continue; fi
  got=$(sha_of "$path")
  if [ "$got" != "$want" ]; then echo "MISMATCH $path: got $got want $want" >&2; bad=$((bad + 1)); fi
done < <(lockq outputs)
[ "$bad" -eq 0 ] || die "$bad of $total output file(s) failed sha256 verification"
log "OK: all $total output file(s) match source-lock.json"
